// Recorded samples (CC0 field recordings, see public/audio/CREDITS.md) that replace synthesis
// recipes where a good recording exists. Synthesis stays as the fallback: a sound plays from its
// recipe until its sample has been fetched and decoded, and forever if loading fails.
//
// Files live in public/audio/{sfx,amb}/ and are fetched lazily relative to Vite's BASE_URL.
// The manifest block below is generated by the asset build script; levels are baked into the
// files (one-shots: loudest 50 ms ≈ -20 dBFS like a centred footstep; beds: RMS targets per
// room), so `gain` is only a trim to tune by ear.

import type { AmbienceId, SfxId } from './catalog';
import type { SfxRecipe } from './core';

export interface SfxSample {
  /** Paths relative to /audio/; one is picked per play (never the same twice in a row). */
  readonly files: readonly string[];
  /** Level trim on top of the level baked into the file. */
  readonly gain: number;
  /** Playback-rate multiplier (pitch) applied on top of the caller's rate. */
  readonly rate?: number;
  /** Per-play random pitch variation (fraction). Default 0.03. */
  readonly jitter?: number;
  /** Extra send into the room reverb (sounds that should bloom regardless of distance). */
  readonly wet?: number;
  /** Move along the base direction while playing: [fromDeg, toDeg, radiusScale]. */
  readonly move?: readonly [number, number, number];
}

export interface AmbienceSample {
  readonly files: readonly string[];
  readonly gain: number;
  readonly loop: true;
  /** Seamless loop region inside the file (seconds); the file carries pre/post padding. */
  readonly loopStart: number;
  readonly loopEnd: number;
  /** Also run the layer's sparse procedural events (SAMPLE_EXTRAS in ambience.ts). */
  readonly extras?: boolean;
  /** One channel: a place with no stereo image worth its memory (half the decoded size). */
  readonly mono?: boolean;
}

